// A PRICE SERIES, AND THE GATE EVERYTHING DERIVED HAS TO PASS THROUGH.
//
// This is `reconcile` for market data, and it exists for the same reason: arithmetic over a series
// that is subtly wrong does not produce an error, it produces a BACKTEST THAT LOOKS GOOD. Every way
// a price series lies is a way a strategy appears profitable, and none of them announce themselves.
//
// THE FOUR THAT MATTER, in the order they cost you money:
//
//  1. LOOK-AHEAD. Deciding a trade on a bar you could not have seen yet. Using today's CLOSE to
//     choose today's entry is the single most common backtest bug and it is invisible, because the
//     equity curve it produces is beautiful. `barsAvailableAt` is the whole answer: it hands back
//     only bars STRICTLY BEFORE the decision date, so the wrong thing is awkward to write rather
//     than merely discouraged.
//
//  2. SURVIVORSHIP. A universe of "the stocks that exist today" backtested over ten years has
//     silently excluded everything that went to zero. The bias is enormous and it is invisible in
//     the data — nothing in a series says what is missing from it. So it is DECLARED, never
//     inferred, and a universe-level claim on a series that has not declared it is refused.
//
//  3. CORPORATE ACTIONS. An unadjusted series shows a 2-for-1 split as a −50% day. A strategy that
//     buys drops finds a great many of them. Adjusted-ness is declared too, and a split-shaped move
//     in a series claiming to be unadjusted is reported as a probable corporate action rather than
//     as a return.
//
//  4. STALE AND MISSING BARS. A feed repeating its last value looks exactly like zero volatility,
//     which is a wonderful thing to be short. A missing day is a hole a strategy steps over without
//     noticing.
import { type Money, money } from "@/features/finance/lib/money";

/** One bar. Prices are integer minor units at the series' declared scale — never floats. */
export interface Bar {
  /** `YYYY-MM-DD`. */
  readonly date: string;
  readonly open: Money;
  readonly high: Money;
  readonly low: Money;
  readonly close: Money;
  /** Share/contract count. Absent means the source did not carry it — not zero. */
  readonly volume?: number;
}

/** What the CALLER asserts about where the series came from. None of this is inferable. */
export interface SeriesMeta {
  readonly symbol: string;
  /** Split- and dividend-adjusted. UNDEFINED means nobody said, which is not the same as false. */
  readonly adjusted?: boolean;
  /** The universe this came from includes delisted names. UNDEFINED means nobody said. */
  readonly survivorshipFree?: boolean;
  readonly source: string;
  /** Minor units per whole unit of price — 100 for cents. Declared, because an option quoted in
   *  hundredths of a cent and an equity quoted in cents are both "integers". */
  readonly minorPerUnit: number;
}

export type SeriesProblemKind =
  | "out-of-order"
  | "duplicate"
  | "non-positive"
  | "impossible-bar"
  | "gap"
  | "stale"
  | "probable-corporate-action";

export interface SeriesProblem {
  readonly kind: SeriesProblemKind;
  readonly at: string;
  readonly detail: string;
}

declare const VERIFIED: unique symbol;

/**
 * A series something has actually checked.
 *
 * Only `checkSeries` and the deliberately-named `unverifiedSeries` can produce one, so a backtest
 * that asks for a `VerifiedSeries` cannot be handed a raw array. Same mechanism as
 * `ReconciledLedger`, for the same reason.
 */
export interface VerifiedSeries {
  readonly [VERIFIED]: true;
  readonly bars: readonly Bar[];
  readonly meta: SeriesMeta;
  readonly unverified: boolean;
  readonly caveat?: string;
}

export interface SeriesCheck {
  readonly ok: boolean;
  readonly series?: VerifiedSeries;
  readonly problems: readonly SeriesProblem[];
}

export interface CheckOptions {
  /** Trading days the market was closed. Without one, a holiday reads as a gap — the check says so
   *  rather than pretending it can tell them apart. */
  readonly holidays?: ReadonlySet<string>;
  /** Identical closes in a row before it is called stale. */
  readonly staleRun?: number;
  /** A single-day move at or beyond this, in an UNADJUSTED series, reads as a corporate action. */
  readonly splitMove?: number;
}

const isWeekend = (iso: string): boolean => {
  const d = new Date(`${iso}T00:00:00Z`).getUTCDay();
  return d === 0 || d === 6;
};

const nextDay = (iso: string): string =>
  new Date(Date.parse(`${iso}T00:00:00Z`) + 86_400_000).toISOString().slice(0, 10);

/** The ONLY place the brand is asserted. Private, because that is the enforcement. */
const mint = (s: Omit<VerifiedSeries, typeof VERIFIED>): VerifiedSeries => s as VerifiedSeries;

export function checkSeries(bars: readonly Bar[], meta: SeriesMeta, opts: CheckOptions = {}): SeriesCheck {
  const { holidays = new Set<string>(), staleRun = 5, splitMove = 0.4 } = opts;
  const problems: SeriesProblem[] = [];

  for (let i = 0; i < bars.length; i++) {
    const b = bars[i];
    const prev = i > 0 ? bars[i - 1] : undefined;

    if (prev && b.date === prev.date) {
      problems.push({ kind: "duplicate", at: b.date, detail: "two bars share one date" });
    } else if (prev && b.date < prev.date) {
      problems.push({ kind: "out-of-order", at: b.date, detail: `follows ${prev.date}` });
    }

    if ([b.open, b.high, b.low, b.close].some((p) => p.minor <= 0)) {
      // A zero or negative price is not a price. It is a parse failure or a padded row, and a
      // return computed across one is arbitrarily large.
      problems.push({ kind: "non-positive", at: b.date, detail: "a price is zero or negative" });
    } else if (b.high.minor < b.low.minor || b.close.minor > b.high.minor || b.close.minor < b.low.minor || b.open.minor > b.high.minor || b.open.minor < b.low.minor) {
      problems.push({ kind: "impossible-bar", at: b.date, detail: "open/close outside high/low, or high below low" });
    }

    if (prev && prev.close.minor > 0) {
      const move = (b.close.minor - prev.close.minor) / prev.close.minor;
      // A 2-for-1 split is −50%. In a series that says it is adjusted this is a real move; in one
      // that says it is not, it is almost certainly a corporate action, and a strategy that buys
      // drops will find a great many of them.
      if (meta.adjusted === false && Math.abs(move) >= splitMove) {
        problems.push({
          kind: "probable-corporate-action",
          at: b.date,
          detail: `${Math.round(move * 100)}% in one day in a series declared UNADJUSTED — a split or a distribution, not a return`,
        });
      }
    }

    // A missing WEEKDAY. Without an exchange calendar this cannot tell a holiday from a hole, and
    // saying so is better than a silent false positive on every public holiday.
    if (prev) {
      for (let d = nextDay(prev.date); d < b.date; d = nextDay(d)) {
        if (!isWeekend(d) && !holidays.has(d)) {
          problems.push({
            kind: "gap",
            at: d,
            detail: "no bar on a weekday — a market holiday if a calendar says so, a hole in the data if not",
          });
        }
      }
    }
  }

  let run = 1;
  for (let i = 1; i < bars.length; i++) {
    if (bars[i].close.minor === bars[i - 1].close.minor) {
      run++;
      if (run === staleRun) {
        // A repeating feed looks exactly like zero volatility, which is a wonderful thing to be short.
        problems.push({
          kind: "stale",
          at: bars[i].date,
          detail: `${staleRun} identical closes in a row — a dead feed and a genuinely flat market are indistinguishable here`,
        });
      }
    } else run = 1;
  }

  const ok = problems.length === 0 && bars.length > 0;
  return {
    ok,
    series: ok ? mint({ bars: [...bars], meta, unverified: false }) : undefined,
    problems,
  };
}

/**
 * A series accepted WITHOUT the check, because refusing outright makes a system nobody uses.
 *
 * Deliberately ugly: it demands a reason, marks the series, and its name is greppable — so "which of
 * these results rest on unchecked data?" has an answer.
 */
export function unverifiedSeries(bars: readonly Bar[], meta: SeriesMeta, caveat: string): VerifiedSeries {
  if (!caveat.trim()) throw new Error("an unverified series must say why it could not be checked");
  return mint({ bars: [...bars], meta, unverified: true, caveat });
}

/**
 * THE LOOK-AHEAD GUARD, and the most important function here.
 *
 * Everything you could have known when deciding on `date` — which is every bar STRICTLY BEFORE it.
 * Not up to and including: on the morning of a decision, that day's high, low and close do not exist
 * yet, and a backtest that reads them produces an equity curve that cannot be traded.
 *
 * Written as the only supported way to slice a series for a decision, so the wrong thing takes
 * deliberate effort rather than merely being discouraged in a comment.
 */
export const barsAvailableAt = (s: VerifiedSeries, date: string): readonly Bar[] =>
  s.bars.filter((b) => b.date < date);

/** The most recent bar that existed before a decision date, if any. */
export const lastBarBefore = (s: VerifiedSeries, date: string): Bar | undefined => {
  const available = barsAvailableAt(s, date);
  return available[available.length - 1];
};

/**
 * Whether a UNIVERSE-level claim may be made from this series.
 *
 * "This strategy beats the index" is a claim about a universe, and it is meaningless on a series
 * that has not declared itself survivorship-free — the losers are missing and nothing in the data
 * says so. Single-instrument claims are unaffected.
 */
export function mayMakeUniverseClaim(s: VerifiedSeries): { allowed: boolean; why: string } {
  if (s.meta.survivorshipFree === true) return { allowed: true, why: "the universe declares it includes delisted names" };
  if (s.meta.survivorshipFree === false) {
    return { allowed: false, why: "the universe EXCLUDES delisted names — every company that went to zero is missing, and no result computed across it is comparable to an index" };
  }
  return {
    allowed: false,
    why: "nobody declared whether this universe includes delisted names, and it cannot be inferred from the data — absent is not the same as false, and neither is safe to build a universe claim on",
  };
}

/** One line stating what a result rests on. */
export function provenance(s: VerifiedSeries): string {
  const adj = s.meta.adjusted === true ? "adjusted" : s.meta.adjusted === false ? "UNADJUSTED" : "adjustment UNDECLARED";
  const base = `${s.meta.symbol} · ${s.bars.length} bar(s) · ${adj} · ${s.meta.source}`;
  return s.unverified ? `UNVERIFIED — ${s.caveat} · ${base}` : `checked · ${base}`;
}

/** Simple return between two bars, as a fraction. Undefined where the base is not a price. */
export function periodReturn(from: Bar, to: Bar): number | undefined {
  if (from.close.minor <= 0) return undefined;
  return (to.close.minor - from.close.minor) / from.close.minor;
}

/** Build a price at the series' declared scale, so a caller cannot silently mix scales. */
export const price = (units: number, meta: SeriesMeta, currency = "USD"): Money =>
  money(Math.round(units * meta.minorPerUnit), currency);

