import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import {
  type Bar,
  type SeriesMeta,
  barsAvailableAt,
  checkSeries,
  lastBarBefore,
  mayMakeUniverseClaim,
  periodReturn,
  provenance,
  unverifiedSeries,
} from "@/features/finance/lib/series";

// SYNTHETIC FIXTURES ONLY. Every price below is invented; no real market data belongs in this repo.
const usd = (major: number): Money => fromMajor(major, "USD");

const meta = (over: Partial<SeriesMeta> = {}): SeriesMeta => ({
  symbol: "EXMPL",
  source: "synthetic",
  minorPerUnit: 100,
  adjusted: true,
  survivorshipFree: true,
  ...over,
});

/** A flat bar at one price, so a test can vary exactly the thing it is about. */
const bar = (date: string, close: number, over: Partial<Bar> = {}): Bar => ({
  date,
  open: usd(close),
  high: usd(close),
  low: usd(close),
  close: usd(close),
  volume: 1000,
  ...over,
});

/** Consecutive WEEKDAYS, so the gap check has nothing to complain about by default. */
const weekdays = (from: string, n: number): string[] => {
  const out: string[] = [];
  let t = Date.parse(`${from}T00:00:00Z`);
  while (out.length < n) {
    const d = new Date(t);
    const day = d.getUTCDay();
    if (day !== 0 && day !== 6) out.push(d.toISOString().slice(0, 10));
    t += 86_400_000;
  }
  return out;
};

const rising = (n: number): Bar[] => weekdays("2026-06-01", n).map((d, i) => bar(d, 100 + i));

describe("THE LOOK-AHEAD GUARD", () => {
  const s = checkSeries(rising(5), meta()).series!;

  it("hands back only bars STRICTLY BEFORE the decision date", () => {
    // On the morning of a decision, that day's high, low and close do not exist yet. A backtest that
    // reads them produces an equity curve that cannot be traded — and a beautiful one.
    const days = s.bars.map((b) => b.date);
    const seen = barsAvailableAt(s, days[2]).map((b) => b.date);
    expect(seen).toEqual([days[0], days[1]]);
    expect(seen).not.toContain(days[2]);
  });

  it("sees nothing at all on the first bar's own date", () => {
    expect(barsAvailableAt(s, s.bars[0].date)).toEqual([]);
    expect(lastBarBefore(s, s.bars[0].date)).toBeUndefined();
  });

  it("gives the most recent bar that existed, not the current one", () => {
    const days = s.bars.map((b) => b.date);
    expect(lastBarBefore(s, days[3])!.date).toBe(days[2]);
  });

  it("sees the whole history for a date past the end", () => {
    expect(barsAvailableAt(s, "2030-01-01")).toHaveLength(5);
  });
});

describe("SURVIVORSHIP is declared, never inferred", () => {
  const bars = rising(5);

  it("refuses a universe claim when nobody declared it", () => {
    // Nothing in a series says what is MISSING from it. Absent is not false, and neither is safe.
    const s = checkSeries(bars, meta({ survivorshipFree: undefined })).series!;
    const v = mayMakeUniverseClaim(s);
    expect(v.allowed).toBe(false);
    expect(v.why).toContain("cannot be inferred");
    expect(v.why).toContain("absent is not the same as false");
  });

  it("refuses outright when the universe is known to exclude the dead", () => {
    const s = checkSeries(bars, meta({ survivorshipFree: false })).series!;
    const v = mayMakeUniverseClaim(s);
    expect(v.allowed).toBe(false);
    expect(v.why).toContain("every company that went to zero is missing");
  });

  it("allows it only on a universe that says it includes delisted names", () => {
    const s = checkSeries(bars, meta({ survivorshipFree: true })).series!;
    expect(mayMakeUniverseClaim(s).allowed).toBe(true);
  });
});

describe("CORPORATE ACTIONS are not returns", () => {
  it("calls a split-shaped drop a probable corporate action in an UNADJUSTED series", () => {
    // A 2-for-1 split is -50%. A strategy that buys drops finds a great many of them.
    const days = weekdays("2026-06-01", 3);
    const bars = [bar(days[0], 100), bar(days[1], 100), bar(days[2], 50)];
    const r = checkSeries(bars, meta({ adjusted: false }));
    expect(r.ok).toBe(false);
    const p = r.problems.find((x) => x.kind === "probable-corporate-action")!;
    expect(p.detail).toContain("-50%");
    expect(p.detail).toContain("not a return");
  });

  it("leaves the same move alone in a series that says it IS adjusted", () => {
    const days = weekdays("2026-06-01", 3);
    const bars = [bar(days[0], 100), bar(days[1], 100), bar(days[2], 50)];
    const r = checkSeries(bars, meta({ adjusted: true }));
    expect(r.problems.filter((x) => x.kind === "probable-corporate-action")).toEqual([]);
  });

  it("says so in the provenance when adjustment was never declared", () => {
    const s = checkSeries(rising(3), meta({ adjusted: undefined })).series!;
    expect(provenance(s)).toContain("adjustment UNDECLARED");
  });
});

describe("the shapes a bad series takes", () => {
  it("catches a bar that cannot exist", () => {
    const days = weekdays("2026-06-01", 2);
    const bars = [bar(days[0], 100), { ...bar(days[1], 100), high: usd(90), low: usd(110) }];
    const r = checkSeries(bars, meta());
    expect(r.problems.some((p) => p.kind === "impossible-bar")).toBe(true);
    expect(r.ok).toBe(false);
  });

  it("catches a close outside its own high/low", () => {
    const days = weekdays("2026-06-01", 1);
    const bars = [{ ...bar(days[0], 100), high: usd(105), low: usd(95), close: usd(120) }];
    expect(checkSeries(bars, meta()).problems[0].kind).toBe("impossible-bar");
  });

  it("catches a zero price rather than computing an infinite return over it", () => {
    const days = weekdays("2026-06-01", 2);
    const r = checkSeries([bar(days[0], 100), bar(days[1], 0)], meta());
    expect(r.problems.some((p) => p.kind === "non-positive")).toBe(true);
  });

  it("catches duplicate and out-of-order bars", () => {
    const days = weekdays("2026-06-01", 3);
    expect(checkSeries([bar(days[0], 100), bar(days[0], 101)], meta()).problems[0].kind).toBe("duplicate");
    expect(checkSeries([bar(days[2], 100), bar(days[0], 101)], meta()).problems[0].kind).toBe("out-of-order");
  });

  it("catches a stale feed, because it is indistinguishable from zero volatility", () => {
    // A repeating feed looks exactly like a flat market, which is a wonderful thing to be short.
    const bars = weekdays("2026-06-01", 6).map((d) => bar(d, 100));
    const p = checkSeries(bars, meta()).problems.find((x) => x.kind === "stale")!;
    expect(p.detail).toContain("indistinguishable");
  });

  it("does not call four identical closes stale at a threshold of five", () => {
    const bars = weekdays("2026-06-01", 4).map((d) => bar(d, 100));
    expect(checkSeries(bars, meta()).problems.some((p) => p.kind === "stale")).toBe(false);
  });
});

describe("gaps, and being honest about what a gap check can know", () => {
  it("flags a missing weekday", () => {
    const days = weekdays("2026-06-01", 4);
    const bars = [bar(days[0], 100), bar(days[1], 101), bar(days[3], 102)];
    const gap = checkSeries(bars, meta()).problems.find((p) => p.kind === "gap")!;
    expect(gap.at).toBe(days[2]);
  });

  it("does NOT flag a weekend", () => {
    // Friday to Monday is not a hole.
    const bars = [bar("2026-06-05", 100), bar("2026-06-08", 101)];
    expect(checkSeries(bars, meta()).problems.filter((p) => p.kind === "gap")).toEqual([]);
  });

  it("takes a holiday calendar, and says it cannot tell one from a hole without it", () => {
    const days = weekdays("2026-06-01", 4);
    const bars = [bar(days[0], 100), bar(days[1], 101), bar(days[3], 102)];
    expect(checkSeries(bars, meta(), { holidays: new Set([days[2]]) }).problems.filter((p) => p.kind === "gap")).toEqual([]);
    const without = checkSeries(bars, meta()).problems.find((p) => p.kind === "gap")!;
    expect(without.detail).toContain("a hole in the data if not");
  });
});

describe("the series is a TYPE, and the escape hatch is ugly", () => {
  it("mints nothing when anything is wrong — there is no partial pass", () => {
    const days = weekdays("2026-06-01", 2);
    const r = checkSeries([bar(days[0], 100), bar(days[1], 0)], meta());
    expect(r.ok).toBe(false);
    expect(r.series).toBeUndefined();
  });

  it("mints nothing from an empty series either", () => {
    const r = checkSeries([], meta());
    expect(r.ok).toBe(false);
    expect(r.series).toBeUndefined();
  });

  it("demands a reason for an unverified series, and marks it", () => {
    expect(() => unverifiedSeries(rising(2), meta(), "  ")).toThrow(/why/);
    const s = unverifiedSeries(rising(2), meta(), "vendor file has no adjustment column");
    expect(s.unverified).toBe(true);
    expect(provenance(s)).toMatch(/^UNVERIFIED/);
    expect(provenance(s)).toContain("vendor file has no adjustment column");
  });

  it("a checked series says so instead", () => {
    expect(provenance(checkSeries(rising(3), meta()).series!)).toMatch(/^checked/);
  });
});

describe("periodReturn", () => {
  it("is the simple return between two closes", () => {
    expect(periodReturn(bar("2026-06-01", 100), bar("2026-06-02", 110))).toBeCloseTo(0.1, 10);
    expect(periodReturn(bar("2026-06-01", 100), bar("2026-06-02", 90))).toBeCloseTo(-0.1, 10);
  });

  it("is undefined over a base that is not a price, rather than infinite", () => {
    expect(periodReturn(bar("2026-06-01", 0), bar("2026-06-02", 110))).toBeUndefined();
  });
});
